} else if (key === "Escape") {
  // Hitting Escape:
  // - Closes submenu.
  // - Moves focus to parent menubar item.
  preventEvent(event);
  // Close this submenu via its toggle in the parent menu.
  const parentMenu = this.elements.parentMenu;
  if (parentMenu) {
    const toggle = parentMenu.currentMenuItem.elements.toggle;
    toggle.close();
    // Move focus to the toggle (parent menu item)
    parentMenu.focusCurrentChild();
  } else {
    // Fallback: close all children and focus controller (should not happen)
    this.closeChildren();
    this.focusController();
  }
}
